48	/**
49	 * @brief Verify properties and throw VerificationError on errors (used by VerificationInstrument)
50	 *
51	 * Throws the same type as PropertyVerifierRegistry::VerifyPropertiesOrThrow. Both report a failure
52	 * of the *same* properties from the *same* registry, so they must not surface as different Python
53	 * types -- otherwise the exception a caller sees depends on whether a VerificationInstrument
54	 * happens to be installed (i.e. on PYPTO_VERIFY_LEVEL), which is a test-harness detail.
55	 */
56	void VerifyOrThrowWithContext(const IRPropertySet& properties, const ProgramPtr& program,
57	                              const std::string& context_msg) {
58	  if (properties.Empty()) {
59	    return;
60	  }
61	
62	  auto& registry = PropertyVerifierRegistry::GetInstance();
63	  auto diagnostics = registry.VerifyProperties(properties, program);
64	
65	  bool has_errors = std::any_of(diagnostics.begin(), diagnostics.end(),
66	                                [](const Diagnostic& d) { return d.severity == DiagnosticSeverity::Error; });
67	  if (has_errors) {
68	    std::string report = PropertyVerifierRegistry::GenerateReport(diagnostics);
69	    throw VerificationError(context_msg + ":\n" + report, std::move(diagnostics));
70	  }
71	}
