122	/// Format one diagnostic as a single line of text. Used both for stderr and
123	/// the perf_hints.log file so the two views stay consistent.
124	std::string FormatDiagnosticLine(const Diagnostic& d, const std::string& phase_label) {
125	  std::ostringstream out;
126	  switch (d.severity) {
127	    case DiagnosticSeverity::Warning:
128	      out << "[warning] [" << d.rule_name << "]";
129	      if (!phase_label.empty()) out << " (" << phase_label << ")";
130	      out << " " << d.message;
131	      if (d.span.is_valid()) out << " at " << d.span.to_string();
132	      break;
133	    case DiagnosticSeverity::PerfHint:
134	      out << "[perf_hint";
135	      if (!d.hint_code.empty()) out << " " << d.hint_code;
136	      out << "] " << d.rule_name << ": " << d.message;
137	      if (d.span.is_valid()) out << " at " << d.span.to_string();
138	      break;
139	    case DiagnosticSeverity::Error:
140	      // EmitDiagnostics never receives Error severity; guarded below.
141	      out << "[error] [" << d.rule_name << "] " << d.message;
142	      break;
143	  }
144	  return out.str();
145	}
