147	/// Find the output_dir of the first ReportInstrument in the active context,
148	/// or the empty string if there is no context or no ReportInstrument.
149	std::string FindReportOutputDir() {
150	  const auto* ctx = PassContext::Current();
151	  if (ctx == nullptr) return {};
152	  for (const auto& inst : ctx->GetInstruments()) {
153	    if (auto* r = dynamic_cast<ReportInstrument*>(inst.get())) {
154	      return r->GetOutputDir();
155	    }
156	  }
157	  return {};
158	}
