161	
162	void EmitDiagnostics(const std::vector<Diagnostic>& diags, const std::string& phase_label) {
163	  if (diags.empty()) return;
164	
165	  // PerfHint detail is persisted to `${ReportInstrument.output_dir}/perf_hints.log`
166	  // only when a ReportInstrument is registered. When that file exists we collapse
167	  // perf hints to a single console summary that points at it; otherwise (bare
168	  // PassPipeline, some tools/tests) we keep printing each hint so they don't go
169	  // dark. Regular warnings always print in full.
170	  const std::string dir = FindReportOutputDir();
171	  const std::string perf_log_path = dir.empty() ? std::string{} : dir + "/perf_hints.log";
172	
173	  // Single pre-scan: count perf hints and collect their distinct source sites,
174	  // but only when we'll actually write a perf_hints.log to point users at.
175	  std::size_t perf_hint_count = 0;
176	  std::set<std::string> perf_hint_sites;
177	  if (!perf_log_path.empty()) {
178	    for (const auto& d : diags) {
179	      if (d.severity != DiagnosticSeverity::PerfHint) continue;
180	      ++perf_hint_count;
181	      if (d.span.is_valid()) perf_hint_sites.insert(d.span.to_string());
182	    }
183	  }
184	  const bool summarize_perf_hints = perf_hint_count > 0;  // implies !perf_log_path.empty()
185	
186	  // 1. stderr — every diagnostic, gated by LogLevel; perf hints collapsed to a
187	  //    summary line when their detail is going to perf_hints.log instead.
188	  for (const auto& d : diags) {
189	    INTERNAL_CHECK_SPAN(d.severity != DiagnosticSeverity::Error, d.span)
190	        << "Error severity must not flow through DiagnosticInstrument: " << d.rule_name;
191	    if (d.severity == DiagnosticSeverity::PerfHint && summarize_perf_hints) continue;
192	    const std::string line = FormatDiagnosticLine(d, phase_label);
193	    if (d.severity == DiagnosticSeverity::Warning) {
194	      LOG_WARN << line;
195	    } else {
196	      LOG_INFO << line;
197	    }
198	  }
199	  if (summarize_perf_hints) {
200	    std::ostringstream summary;
201	    summary << "[perf_hint] " << perf_hint_count << (perf_hint_count == 1 ? " hint" : " hints");
202	    if (!perf_hint_sites.empty()) {
203	      summary << " across " << perf_hint_sites.size() << (perf_hint_sites.size() == 1 ? " site" : " sites");
204	    }
205	    summary << "; see " << perf_log_path;
206	    LOG_INFO << summary.str();
207	  }
208	
209	  // 2. File — only PerfHint, only when a ReportInstrument is registered.
210	  if (!summarize_perf_hints) return;
211	
212	  // PassContext is thread-local, but multiple threads can run concurrent
213	  // pipelines whose distinct ReportInstruments happen to share an output
214	  // directory. Serialise file appends so per-line writes don't interleave.
215	  static std::mutex perf_hints_log_mu;
216	  std::scoped_lock lock(perf_hints_log_mu);
217	
218	  std::ofstream f(perf_log_path, std::ios::app);
219	  if (!f.is_open()) {
220	    // Last resort: the console summary already pointed at this file, but we
221	    // can't write it — don't drop the detail; fall back to per-hint stderr.
222	    LOG_WARN << "Failed to open " << perf_log_path
223	             << " for perf-hint append; emitting hints to stderr instead";
224	    for (const auto& d : diags) {
225	      if (d.severity == DiagnosticSeverity::PerfHint) LOG_INFO << FormatDiagnosticLine(d, phase_label);
226	    }
227	    return;
228	  }
229	  for (const auto& d : diags) {
230	    if (d.severity == DiagnosticSeverity::PerfHint) {
231	      f << FormatDiagnosticLine(d, phase_label) << "\n";
232	    }
233	  }
234	}
