280	/// The wire name of each runtime kind, in enumerator order. Single table so a
281	/// new runtime cannot be added to one direction and forgotten in the other.
282	constexpr std::pair<RuntimeKind, const char*> kRuntimeNames[] = {
283	    {RuntimeKind::TensorMapAndRingBuffer, "tensormap_and_ringbuffer"},
284	    {RuntimeKind::HostBuildGraph, "host_build_graph"},
285	};
286	
287	std::string RuntimeKindToName(RuntimeKind kind) {
288	  for (const auto& [candidate, name] : kRuntimeNames) {
289	    if (candidate == kind) return name;
290	  }
291	  INTERNAL_UNREACHABLE << "Internal error: unhandled RuntimeKind value " << static_cast<int>(kind);
292	}
293	
294	RuntimeKind RuntimeKindFromName(const std::string& name) {
295	  for (const auto& [kind, candidate] : kRuntimeNames) {
296	    if (name == candidate) return kind;
297	  }
298	  std::ostringstream supported;
299	  for (size_t i = 0; i < std::size(kRuntimeNames); ++i) {
300	    if (i != 0) supported << ", ";
301	    supported << kRuntimeNames[i].second;
302	  }
303	  CHECK(false) << "Unknown runtime '" << name << "': expected one of " << supported.str();
304	  return kDefaultRuntimeKind;  // unreachable; CHECK throws
305	}
